};

useEffect(() => {
  if (tourDates.length > 0 && schedules.length > 0) {
    const cleaned = schedules.filter(s => {
      if (s.crewId !== 'openshifts' && !s.isTimeOff) {
        let lookupDate = s.date;
        const isDefaultMonth = currentWeekStart.getFullYear() === 2023 && currentWeekStart.getMonth() === 0;
        if (isDefaultMonth) {
          if (calendarRange === 'week' && currentWeekStart.getDate() === 23) {
            const mapping: { [key: string]: string } = {
              '2023-01-23': '2026-01-01',
              '2023-01-24': '2026-01-02',
              '2023-01-25': '2026-01-03',
              '2023-01-26': '2026-01-04',
              '2023-01-27': '2026-01-05',
              '2023-01-28': '2026-01-06',
              '2023-01-29': '2026-01-08'
            };
            if (mapping[s.date]) {
              lookupDate = mapping[s.date];
            }
          } else if (s.date.startsWith('2023-01-')) {
            lookupDate = s.date.replace('2023-01-', '2026-01-');
          }
        }
        const hasShow = tourDates.some(show => show.date === lookupDate);
        return hasShow;
      }
      return true;
    });

    if (cleaned.length !== schedules.length) {
      setSchedules(cleaned);
      localStorage.setItem('7h_crew_schedules', JSON.stringify(cleaned));
      window.dispatchEvent(new Event('storage'));

      fetch("/api/crew/calendar", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(cleaned)
      }).catch(err => console.error("Failed to sync schedules:", err));
    }
  }
}, [tourDates, schedules, currentWeekStart, calendarRange]);

